  PROCEDURE work(a VARCHAR2) IS
  BEGIN
    INSERT INTO text_log VALUES (a);
  END work;
  PROCEDURE work(a NUMBER) IS
  BEGIN
    INSERT INTO number_log VALUES (a);
  END work;
END p;

PACKAGE BODY p AS
  PROCEDURE work(a IN NUMBER, b IN OUT NOCOPY VARCHAR2) IS
  BEGIN
    INSERT INTO number_log VALUES (a);
  END work;
  PROCEDURE work(a VARCHAR2 DEFAULT 'none') IS
  BEGIN
    INSERT INTO text_log VALUES (a);
  END work;
  FUNCTION work(a DATE := SYSDATE) RETURN NUMBER IS
  BEGIN
    RETURN 1;
  END work;
END p;

